package store

import (
	"context"
	"database/sql"
	"encoding/hex"
	"encoding/json"
	"os"
	"path/filepath"
	"strings"

	accountlabel "dyna-agent/internal/account/label"
)

// migratePiLabels treats only exact labels generated by older Pi code as
// defaults. Other labels belong to the owner. It reads only the account's
// private auth file, and never stores credentials in the registry.
func migratePiLabels(ctx context.Context, conn *sql.Conn, dataDir string) error {
	rows, err := conn.QueryContext(ctx, "SELECT id, metadata FROM accounts")
	if err != nil {
		return err
	}
	type row struct {
		id   string
		meta Metadata
	}
	var pending []row
	for rows.Next() {
		var id string
		var raw []byte
		if err := rows.Scan(&id, &raw); err != nil {
			rows.Close()
			return err
		}
		var meta Metadata
		if err := json.Unmarshal(raw, &meta); err != nil {
			rows.Close()
			return err
		}
		pending = append(pending, row{id, meta})
	}
	err = rows.Err()
	rows.Close()
	if err != nil {
		return err
	}
	for _, r := range pending {
		m := r.meta
		if m.LabelSource != "" {
			continue
		}
		source := LabelOwner
		next := m.Label
		id := strings.TrimPrefix(m.Identity, "pi:")
		generic := m.Harness == "pi" && (m.Label == "pi native login" || (id != m.Identity && id != "" && m.Label == id+" login"))
		if generic {
			source = LabelDefault
			// Account IDs are random 16-byte hex strings. Construct the path
			// rather than trusting a path stored in account metadata.
			decoded, e := hex.DecodeString(r.id)
			if e == nil && len(decoded) == 16 {
				path := filepath.Join(dataDir, "accounts", "pi", r.id, "auth.json")
				info, e := os.Lstat(path)
				if e == nil && info.Mode().IsRegular() && info.Size() <= 4<<20 {
					raw, e := os.ReadFile(path)
					var entries map[string]json.RawMessage
					if e == nil && json.Unmarshal(raw, &entries) == nil && len(entries) == 1 {
						for provider, entry := range entries {
							next = accountlabel.PiDefaultLabel(provider, entry)
						}
					}
				}
			}
		}
		if _, err := conn.ExecContext(ctx, `UPDATE accounts SET metadata = json_set(CAST(metadata AS TEXT), '$.label', ?, '$.labelSource', ?) WHERE id = ?`, next, source, r.id); err != nil {
			return err
		}
	}
	return nil
}
